//let arr = $[0].objs.sort((a,b)=>a.steps>b.steps ? 1 : a.steps < b.steps ? -1 : a.from < b.from ? 1 : -1)

// this should probably use a for loop for performance reasons (lots of object re-creation/cloning w/ reduce)
return $.reduce((a,c,i)=>{
  const d = [...a.nodes]
  const w = [...a.width]
 //d.length===c.steps+1 ? d.push({[c.from]:[c.to]}) : d[c.steps+1][c.from] ? d[c.steps+1][c.from] = [...d[c.steps+1][c.from],c.to] : d[c.steps+1][c.from]=[c.to]
  //{[arr[0].to]:[]}
  if (d.length===c.steps) {
    d.push({[`${c.to}:${c.toProcess}`]:[{"id":`${c.from}:${c.fromProcess}`,"qty":c.quantity}]})
    w[c.steps] = 1
  }
  else {
    if(d[c.steps][`${c.to}:${c.toProcess}`]) { 
      d[c.steps][`${c.to}:${c.toProcess}`] = [...d[c.steps][`${c.to}:${c.toProcess}`],{"id":`${c.from}:${c.fromProcess}`,"qty":c.quantity}]
      w[c.steps] += 1
    }
    else {
      d[c.steps][`${c.to}:${c.toProcess}`]=[{"id":`${c.from}:${c.fromProcess}`,"qty":c.quantity}]
      w[c.steps] += 1
    }
  }

  return {
    "nodes": d,
    "width": w,
    "max": w[c.steps] > a.max.val ? {"pos":c.steps, "val": w[c.steps]} : a.max
  }
},{"nodes":[], "width": [], "max":{"pos":0, "val":0}})

