//let arr = $[0].objs.sort((a,b)=>a.steps>b.steps ? 1 : a.steps < b.steps ? -1 : a.from < b.from ? 1 : -1)



// this should probably use a for loop for performance reasons (lots of object re-creation/cloning w/ reduce)
return $.reduce((a,c,i)=>{
  const d = [...a.nodes]
  const w = [...a.width]


  if (d.length===c.steps) {
    d.push({[`${c.from}:${c.fromProcess}:${c.fromLocation}:${c.fromStatus}`]:[{"id":`${c.to}:${c.toProcess}:${c.toLocation}:${c.toStatus}`,"qty":c.quantity}]})
    w[c.steps] = 1
  }
  else {
    if(d[c.steps][`${c.from}:${c.fromProcess}:${c.fromLocation}:${c.fromStatus}`]) { 
      d[c.steps][`${c.from}:${c.fromProcess}:${c.fromLocation}:${c.fromStatus}`] = [...d[c.steps][`${c.from}:${c.fromProcess}:${c.fromLocation}:${c.fromStatus}`],{"id":`${c.to}:${c.toProcess}:${c.toLocation}:${c.toStatus}`,"qty":c.quantity}]
      w[c.steps] += 1
    }
    else {
      d[c.steps][`${c.from}:${c.fromProcess}:${c.fromLocation}:${c.fromStatus}`]=[{"id":`${c.to}:${c.toProcess}:${c.toLocation}:${c.toStatus}`,"qty":c.quantity}]
      w[c.steps] += 1
    }
  }

  return {
    "nodes": d,
    "width": w,
    "max": w[c.steps] > a.max.val ? {"pos":c.steps, "val": w[c.steps]} : a.max
  }
},{"nodes":[], "width": [], "max":{"pos":0, "val":0}})

const maxVal = Math.max($.Downstream.max.val, $.Upstream.max.val,0)

