      "alpha": "100"
    })))
  }
  h+=1
}
}
const uNodes = [...$.Upstream.nodes]
const uWidth = [...$.Upstream.width]
const dY = data.length ? data[data.length-1].y+tier : tier

if (uNodes.length){

